    let callCount = 0;
    const provider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        callCount++;
        if (callCount === 1) {
          yield {type: 'tool_use', toolCall: {id: 'c1', name: 'my_tool', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }

