import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<(input: Record<string, unknown>) => Promise<string>>().mockResolvedValue('success');

      registry.register(
        {
          name: 'test-tool',
          description: 'A test tool',
          inputSchema: {
            type: 'object',
            properties: {
              location: {type: 'string'},
            },
            required: ['location'],
          },
        },
        execute
      );

      const response = await registry.execute('test-tool', {});
      const mockState = execute.mock;

      expect({calls: mockState.calls.length, result: response.result}).toEqual({
        calls: 0,
        result: expect.stringContaining("must have required property 'location'"),
      });
    });

    it('passes valid input with an unlisted extra property through to the executor unchanged exactly once', async () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<(input: Record<string, unknown>) => Promise<string>>().mockResolvedValue('success');

      registry.register(
        {
          name: 'test-tool',
          description: 'A test tool',
          inputSchema: {
            type: 'object',
            properties: {
              location: {type: 'string'},
            },
            required: ['location'],
          },
        },
        execute
      );

      const input = {location: 'Paris', extra: 'data'};
      await registry.execute('test-tool', input);

      expect(execute).toHaveBeenCalledTimes(1);
      expect(execute.mock.calls[0]?.[0]).toEqual(input);
    });

    it('rejects a wrong-typed field with a message naming the field path and expected type, without leaking the value', async () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<(input: Record<string, unknown>) => Promise<string>>().mockResolvedValue('success');

      registry.register(
        {
          name: 'test-tool',
          description: 'A test tool',
          inputSchema: {
            type: 'object',
            properties: {
              location: {type: 'string'},
            },
          },
        },
        execute
      );

      const response = await registry.execute('test-tool', {location: 42});

      expect(execute).not.toHaveBeenCalled();
      expect(response.result).toContain('/location');
      expect(response.result).toContain('must be string');
      expect(response.result).not.toContain('42');
    });

    it('throws Unknown tool: <name> for an unregistered name', async () => {
      const registry = new ToolRegistry();
      await expect(registry.execute('non-existent', {})).rejects.toThrow('Unknown tool: non-existent');
    });

    it('validates a function-valued tool definition against the schema current at that call', async () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<(input: Record<string, unknown>) => Promise<string>>().mockResolvedValue('success');

      let callCount = 0;
      registry.register(() => {
        callCount++;
        return {
          name: 'dynamic-tool',
          description: 'A dynamic tool',
          inputSchema: {
            type: 'object',
            properties: {
              flag: {type: callCount <= 2 ? 'string' : 'number'},
            },
          },
        };
      }, execute);

      let response = await registry.execute('dynamic-tool', {flag: 'value'});
      expect(execute).toHaveBeenCalledTimes(1);
      expect(response).toEqual({result: 'success'});

      response = await registry.execute('dynamic-tool', {flag: 42});
      expect(execute).toHaveBeenCalledTimes(2);
      expect(response).toEqual({result: 'success'});

      response = await registry.execute('dynamic-tool', {flag: 'value'});
      expect(execute).toHaveBeenCalledTimes(2);
      expect(response.result).toContain('must be number');
    });

    it('compiles a static tool schema once across multiple execute calls', async () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<(input: Record<string, unknown>) => Promise<string>>().mockResolvedValue('success');

      const inputSchema = {
        type: 'object',
        properties: {
          location: {type: 'string'},
        },
      } as const;

      registry.register(
        {
          name: 'test-tool',
          description: 'A test tool',
          inputSchema,
        },
        execute
      );

      const originalCompile = (registry as any).ajv.compile.bind((registry as any).ajv);
      const compileSpy = jest.fn(originalCompile);
      (registry as any).ajv.compile = compileSpy;

      for (let i = 0; i < 10; i++) {
        await registry.execute('test-tool', {location: 'Paris'});
      }
      expect(execute).toHaveBeenCalledTimes(10);
      expect(compileSpy).not.toHaveBeenCalled();
    });
  });

  describe('register', () => {
    it('throws at registration time for an uncompilable static schema', () => {
      const registry = new ToolRegistry();
      const execute = jest.fn<(input: Record<string, unknown>) => Promise<string>>().mockResolvedValue('success');

      expect(() => {
        registry.register(
          {
            name: 'bad-tool',
            description: 'A bad tool',
            inputSchema: {
              type: 'object',
              properties: {
                location: {type: 'invalid-type-xyz'},
              },
            },
          },
          execute
        );
      }).toThrow('Failed to compile schema for tool bad-tool');
    });
  });
});

